    if 'levi' in name_lower and 't-shirt' in name_lower:
        tshirt_prod = {"product_id": pid, "name": prod.name, "variants": []}
        for item in prod.items:
            tshirt_prod["variants"].append({"item_id": item.item_id, "options": str(item.options), "price": item.price, "available": item.available})
